fn max(a: Vec<u64>) -> i64 {
    // Convert each u64 to i64 (wrapping modulo 2^64) and take the signed maximum.
    // If the iterator is empty, return -1.
    a.into_iter()
     .map(|x| x as i64)
     .max()
     .unwrap_or(-1)
}

